impl SpatialAudioRuntime {
    /// Evaluates a Timeline-owned voice through the same listener/emitter math as authored
    /// AudioEmitter playback. The clip's gain multiplies the emitter's authored gain while
    /// spatial blend, distance, and rolloff remain owned by the production emitter.
    pub(crate) fn timeline_gains(
        &self,
        source: Entity,
        emitter: &AudioEmitter,
        clip_volume: f32,
    ) -> Option<StereoGains> {
        let pose = self.poses.get(&source).copied()?;
        Some(emitter_gains(
            self.listener,
            pose,
            AudioVoiceSpatialSettings {
                volume: finite_unit(clip_volume) * finite_unit(emitter.volume),
                spatial_blend: emitter.spatial_blend,
                min_distance: emitter.min_distance,
                max_distance: emitter.max_distance,
                rolloff: emitter.rolloff,
            },
        ))
    }
}

